export interface Container8Props {
  /**
   * Variant
   * Friendly names map to internal IDs:
   *   "Variant 1" → LXlajaIQy
   *   "Variant 2" → QbJCujFP1
   */
  variant?: 'Variant 1' | 'Variant 2' | 'LXlajaIQy' | 'QbJCujFP1';
  /**
   * Click — pass as `EtJtGOBdQ` not `click`.
   */
  EtJtGOBdQ?: () => void;
  /**
   * Click 2 — pass as `feaEWrpwv` not `click2`.
   */
  feaEWrpwv?: () => void;
  /**
   * Click 3 — pass as `W5FMhYj8j` not `click3`.
   */
  W5FMhYj8j?: () => void;
  /** Additional properties */
  [key: string]: unknown;
}
